<script setup>
import { onBeforeUnmount, onMounted, ref } from 'vue';
import { api, formatCost, formatDate, formatNumber } from '../api.js';
import EmptyState from '../components/EmptyState.vue';
import UiIcon from '../components/UiIcon.vue';
const logs = ref([]), keys = ref([]), providers = ref([]), loading = ref(true), page = ref(1), pages = ref(1), total = ref(0), expanded = ref(null);
const filters = ref({ key_id: '', provider_id: '', status: '' });
async function load() { loading.value = true; const query = new URLSearchParams({ page: page.value, ...Object.fromEntries(Object.entries(filters.value).filter(([, value]) => value)) }); const data = await api('GET', `/api/admin/usage?${query}`); logs.value = data.logs; pages.value = data.pages; total.value = data.total; loading.value = false; }
function apply() { page.value = 1; load(); }
function move(delta) { page.value += delta; load(); }
onMounted(async () => { await load(); const [k, p] = await Promise.all([api('GET', '/api/admin/keys'), api('GET', '/api/admin/providers')]); keys.value = k.keys; providers.value = p.providers; window.addEventListener('relay-refresh', load); });
onBeforeUnmount(() => window.removeEventListener('relay-refresh', load));
</script>
<template><section class="panel"><header class="panel-header log-header"><div><h2>请求审计 <span class="count">{{ total }}</span></h2><p>按 Key、供应商或执行结果筛选调用记录</p></div><div class="log-filters"><select v-model="filters.key_id" @change="apply"><option value="">全部 Key</option><option v-for="key in keys" :key="key.id" :value="key.id">{{ key.name }}</option></select><select v-model="filters.provider_id" @change="apply"><option value="">全部供应商</option><option v-for="provider in providers" :key="provider.id" :value="provider.id">{{ provider.name }}</option></select><select v-model="filters.status" @change="apply"><option value="">全部状态</option><option value="success">成功</option><option value="error">失败</option></select></div></header><div v-if="loading" class="table-loading">正在查询日志…</div><EmptyState v-else-if="!logs.length" title="没有匹配的请求" text="调整筛选条件，或发起一次 API 调用后再查看。" /><div v-else class="table-wrap"><table class="logs-table"><thead><tr><th>时间 / 请求 ID</th><th>Key / 供应商</th><th>模型</th><th>Token（入 / 出）</th><th>费用</th><th>延迟</th><th>状态</th><th></th></tr></thead><tbody v-for="log in logs" :key="log.id"><tr><td><div>{{ formatDate(log.created_at) }}</div><code class="request-id">{{ log.request_id.slice(0, 8) }}</code></td><td><div>{{ log.key_name || '已删除 Key' }}</div><small class="muted">{{ log.provider_name || '已删除供应商' }}</small></td><td><code class="model-name">{{ log.model || '—' }}</code></td><td>{{ formatNumber(log.prompt_tokens) }} / {{ formatNumber(log.completion_tokens) }}</td><td>{{ formatCost(log.cost_micros / 1e6) }}</td><td>{{ formatNumber(log.latency_ms) }} ms</td><td><span class="badge" :class="log.status < 400 ? 'success' : 'danger'">{{ log.status }}</span></td><td><button v-if="log.error" class="icon-button" @click="expanded = expanded === log.id ? null : log.id"><UiIcon name="info" :size="16" /></button></td></tr><tr v-if="expanded === log.id" class="error-detail"><td colspan="8">{{ log.error }}</td></tr></tbody></table></div><footer class="pagination"><span>第 {{ page }} / {{ pages }} 页</span><div><button class="button small" :disabled="page <= 1" @click="move(-1)">上一页</button><button class="button small" :disabled="page >= pages" @click="move(1)">下一页</button></div></footer></section></template>
